async function main() {
  const tweets = JSON.parse(readFileSync(TWEETS_FILE, 'utf-8'));
  let matched = 0;
  for (const tweet of tweets) {
    if (COMMENTS[tweet.id]) {
      tweet.comment = COMMENTS[tweet.id];
      matched++;
      console.log(`✓ @${tweet.author.username}: ${COMMENTS[tweet.id].substring(0, 50)}...`);
    } else {
      tweet.comment = '';
      console.log(`✗ @${tweet.author.username}: no comment — re-run "write comments" in Claude Code`);
    }
  }
  writeFileSync(TWEETS_FILE, JSON.stringify(tweets, null, 2));
  console.log(`\nDone. Matched ${matched}/${tweets.length} comments.`);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
